"use client";

import { motion, useAnimate } from "motion/react";
import { forwardRef, useCallback, useImperativeHandle, useRef } from "react";

import type { AnimatedIconHandle, AnimatedIconProps } from "./types";

const BrandNotionIcon = forwardRef<AnimatedIconHandle, AnimatedIconProps>(
  ({ size = 24, color = "currentColor", className = "" }, ref) => {
    const [scope, animate] = useAnimate();
    const isAnimatingRef = useRef(false);
    const animationIdRef = useRef(0);

    const start = useCallback(async () => {
      if (isAnimatingRef.current) return;
      isAnimatingRef.current = true;
      const animationId = ++animationIdRef.current;

      await animate(
        ".notion-group, .notion-shell, .notion-letter",
        {
          opacity: 1,
          scale: 1,
          x: 0,
          y: 0,
          rotate: 0,
          skewY: 0,
          filter: "blur(0px)",
        },
        { duration: 0 },
      );

      await animate(
        ".notion-shell",
        {
          opacity: [0.32, 1],
          scale: [0.97, 1.02, 1],
          rotate: [-3.2, 0.6, 0],
          y: [0.2, -0.1, 0],
          filter: ["blur(0.8px)", "blur(0px)"],
        },
        {
          duration: 0.46,
          ease: [0.22, 1, 0.36, 1],
          times: [0, 0.72, 1],
        },
      );
      if (!isAnimatingRef.current || animationIdRef.current !== animationId) {
        return;
      }

      await animate(
        ".notion-letter",
        {
          opacity: [0.38, 1],
          scale: [0.95, 1.04, 1],
          x: [-0.4, 0.14, 0],
          y: [0.28, -0.08, 0],
          filter: ["blur(0.8px)", "blur(0px)"],
        },
        {
          duration: 0.38,
          ease: [0.22, 1, 0.36, 1],
          times: [0, 0.75, 1],
        },
      );
      if (!isAnimatingRef.current || animationIdRef.current !== animationId) {
        return;
      }

      animate(
        ".notion-group",
        { scale: [0.99, 1.015, 1] },
        { duration: 0.22, ease: "easeOut" },
      );

      while (isAnimatingRef.current && animationIdRef.current === animationId) {
        await Promise.all([
          animate(
            ".notion-group",
            {
              y: [0, -0.24, 0.12, 0],
              rotate: [0, -0.85, 0.6, 0],
              scale: [1, 1.012, 0.999, 1],
            },
            { duration: 0.96, ease: "easeInOut" },
          ),
          animate(
            ".notion-shell",
            { skewY: [0, 0.85, 0], x: [0, 0.08, 0] },
            { duration: 0.96, ease: "easeInOut" },
          ),
          animate(
            ".notion-letter",
            { x: [0, 0.18, -0.06, 0], scale: [1, 1.02, 1] },
            { duration: 0.96, ease: "easeInOut" },
          ),
        ]);

        if (!isAnimatingRef.current || animationIdRef.current !== animationId) {
          break;
        }

        await Promise.all([
          animate(
            ".notion-group",
            {
              y: [0, 0.1, 0],
              rotate: [0, 0.35, 0],
              scale: [1, 1.008, 1],
            },
            { duration: 0.72, ease: "easeInOut" },
          ),
          animate(
            ".notion-shell",
            { skewY: [0, -0.5, 0], x: [0, -0.04, 0] },
            { duration: 0.72, ease: "easeInOut" },
          ),
          animate(
            ".notion-letter",
            { x: [0, -0.09, 0], scale: [1, 1.01, 1] },
            { duration: 0.72, ease: "easeInOut" },
          ),
        ]);
      }
    }, [animate]);

    const stop = useCallback(() => {
      isAnimatingRef.current = false;
      animationIdRef.current += 1;

      animate(
        ".notion-group, .notion-shell, .notion-letter",
        {
          opacity: 1,
          scale: 1,
          x: 0,
          y: 0,
          rotate: 0,
          skewY: 0,
          filter: "blur(0px)",
        },
        { duration: 0.22, ease: "easeOut" },
      );
    }, [animate]);

    useImperativeHandle(
      ref,
      () => ({
        startAnimation: start,
        stopAnimation: stop,
      }),
      [start, stop],
    );

    return (
      <motion.svg
        ref={scope}
        onHoverStart={start}
        onHoverEnd={stop}
        fill={color}
        fillRule="evenodd"
        height={size}
        width={size}
        style={{ flex: "none", lineHeight: 1, overflow: "visible" }}
        viewBox="0 0 24 24"
        xmlns="http://www.w3.org/2000/svg"
        className={`notion-icon cursor-pointer select-none ${className}`}
      >
        <title>Notion</title>
        <motion.g
          className="notion-group"
          style={{ transformOrigin: "50% 50%" }}
        >
          <motion.path
            className="notion-shell"
            style={{ transformOrigin: "50% 50%" }}
            initial={{ opacity: 1, scale: 1 }}
            fill={color}
            d="M15.257.055l-13.31.98C.874 1.128.5 1.83.5 2.667v14.559c0 .654.233 1.213.794 1.96l3.129 4.06c.513.653.98.794 1.962.745l15.457-.932c1.307-.093 1.681-.7 1.681-1.727V4.954c0-.53-.21-.684-.829-1.135l-.106-.078L18.34.755c-1.027-.746-1.45-.84-3.083-.7zM6.736 4.685c-1.263.086-1.549.105-2.266-.477L2.647 2.76c-.186-.187-.092-.42.375-.466l12.796-.933c1.074-.094 1.634.28 2.054.606l2.195 1.587c.093.047.326.326.047.326l-13.216.794-.162.01zM5.263 21.193V7.287c0-.606.187-.886.748-.933l15.176-.886c.515-.047.748.28.748.886v13.81c0 .609-.093 1.122-.934 1.168l-14.523.84c-.842.047-1.215-.232-1.215-.98z"
          />
          <motion.path
            className="notion-letter"
            style={{ transformOrigin: "50% 50%" }}
            initial={{ opacity: 1, scale: 1 }}
            fill={color}
            d="M19.601 8.033c.093.422 0 .842-.422.89l-.699.139v10.264c-.608.327-1.168.513-1.635.513-.747 0-.934-.232-1.495-.932l-4.576-7.185v6.952l1.448.327s0 .84-1.169.84l-3.221.186c-.094-.187 0-.654.327-.747l.84-.232V9.853L7.832 9.76c-.093-.42.14-1.026.794-1.073l3.456-.232 4.763 7.279v-6.44l-1.214-.14c-.094-.513.28-.887.747-.933l3.223-.187z"
          />
        </motion.g>
      </motion.svg>
    );
  },
);

BrandNotionIcon.displayName = "BrandNotionIcon";

export default BrandNotionIcon;

import type { SVGMotionProps } from "motion/react";
import type { ComponentType } from "react";

export type HoverlyIconCategory = "All" | "Social" | "UI" | "Arrows";

export interface AnimatedIconHandle {
  startAnimation: () => void | Promise<void>;
  stopAnimation: () => void | Promise<void>;
}

export interface AnimatedIconProps
  extends Omit<SVGMotionProps<SVGSVGElement>, "ref"> {
  size?: number;
  color?: string;
  strokeWidth?: number;
  className?: string;
}

export type HoverlyIconProps = AnimatedIconProps;

export interface IconCliCommand {
  label: string;
  command: string;
}

export interface HoverlyIconRecord {
  slug: string;
  name: string;
  category: Exclude<HoverlyIconCategory, "All">;
  description: string;
  tags: string[];
  componentName: string;
  importPath: string;
  sourceCode: string;
  registryUrl: string;
  cliCommands: IconCliCommand[];
}

export type HoverlyIconComponent = ComponentType<AnimatedIconProps>;
